pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    // Deploy C reference in setUp as required
    function setUp() public { c = new C(); }

    // Fuzz the deciding parameters: from address, a target callee address (we deploy a helper),
    // an array of addresses for _tos and a uint v. The fuzzer will try many combinations.
    function testFuzz_property(address from, uint256 v, address[] memory tos) public {
        // Keep domain wide but ensure tos length is within reasonable gas limits
        vm.assume(tos.length < 10);

        // Deploy a simple callee that accepts the low-level call and returns true for transferFrom signature.
        // This ensures the call inside C succeeds and does not revert, so both reference and mutant complete.
        CalleeGood callee = new CalleeGood();

        // Call C.transfer and capture whether it returns true (or reverts). We must observe the return value.
        bool ok;
        try c.transfer(from, address(callee), tos, uint(v)) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }

        // General rule: for any admissible input where the call does not revert, the reference returns true.
        // We assert that C.transfer returned true. This holds for the reference for all inputs; the mutant
        // that returns _tos.length==0 will fail when tos.length > 0 because it will return false while
        // the reference returns true.
        assertTrue(ok);
    }
}

// Minimal adversarial helper that responds successfully to transferFrom(address,address,uint256)
contract CalleeGood {
    // returns true for any call matching selector; we implement a generic fallback that returns no revert
    fallback() external payable {
        // do nothing, succeed
    }
    receive() external payable {}
}

