pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: from address, an array of target addresses, and a uint value
    function testFuzz_property(address from, address[] memory tos, uint256 v) public {
        // admissible domain: tos must be non-empty because function requires(_tos.length > 0)
        vm.assume(tos.length > 0);

        // The callee address that C will call is provided as the first element of tos.
        // We need a contract at that address that will accept the low-level call and return true.
        // Fuzz provides addresses for tos elements but they are EOAs (no code) so a low-level call to them would succeed
        // but not exercise differing behavior; however the reference behavior relies only on call returning success.
        // To be safe and ensure the call succeeds, deploy a minimal receiver and use its address as the callee.

        // Deploy a simple receiver that always returns true for the called selector
        Receiver r = new Receiver();

        // Replace all tos entries with the receiver address so C.call to caddress succeeds (adversarial counterpart not needed here
        // for causing failure; we just ensure the low-level call returns true)
        for (uint i = 0; i < tos.length; i++) {
            tos[i] = address(r);
        }

        // Call transfer and capture whether it returns true (reference should always return true for non-empty tos when calls succeed)
        bool ok;
        try c.transfer(from, address(r), tos, v) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false; // revert -> treat as false
        }

        // Single assertion: reference implementation always returns true for any admissible input (non-empty tos and successful callee calls)
        // The mutant returns false when _tos.length != 0, so this assertion will fail on the mutant for some fuzz input
        assertTrue(ok);
    }
}

// Minimal receiver that simply returns true for any call and does not revert
contract Receiver {
    fallback() external payable returns (bytes memory) {
        // emulate a successful transferFrom by returning non-empty data
        return abi.encodePacked(true);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz: from address, an array length (we pass a dynamic array by providing length and elements via bytes seed), and value v
    // We let the fuzzer choose an address for 'from' and a uint v and a uint8 count for _tos length, and elementSeed to derive elements.
    function testFuzz_property(address from, uint256 v, uint8 count, bytes32 elementSeed) public {
        // Keep count reasonably bounded but allow zero as well
        uint256 len = uint256(count);
        // Prepare dynamic array of addresses; fill with deployed helper that will accept the low-level call
        address helper = address(new CalleeAccept());

        address[] memory tos = new address[](len);
        for (uint256 i = 0; i < len; i++) {
            // Derive some variability from elementSeed to populate addresses but use the helper so calls succeed
            // Use helper for all entries to ensure external calls succeed (EOA would make call succeed too, but using a contract ensures behaviour)
            tos[i] = helper;
        }

        // The reference C: for any input where transfer does not revert, it returns true.
        // We'll call and capture the return using try/catch since transfer is external and returns (bool).
        bool okRef;
        try c.transfer(from, address(helper), tos, v) returns (bool ret) {
            okRef = ret;
        } catch {
            // If it reverts, we consider okRef = false (call did not complete)
            okRef = false;
        }

        // The general property: if the call completes (okRef==true/false) then for the correct implementation
        // it should be true whenever it completes. So assertTrue(okRef || len == 0 ? true : true);
        // We need exactly one assertTrue that the reference satisfies for ALL inputs and mutant breaks for SOME.
        // The readable property: if the call completed (did not revert) then the reference returns true.
        // We express this by calling again under a try to observe return and then assertTrue(that_return_implies_true).

        // To adhere strictly to rules: observe c only via its public call. We already obtained okRef as the return/completion flag.
        // For the correct contract, whenever the call completes it returns true. Therefore okRef == true whenever the call did not revert.
        // So we assert that either the call reverted (okRef == false) OR it returned true. That simplifies to assertTrue(okRef || !okRef || (len == len));
        // But must be meaningful: assert that if the call completed (i.e., did not revert) then its returned value is true.

        // We can recreate the check explicitly: try call and capture a boolean 'completedAndReturnedTrue'.
        bool completedAndReturnedTrue;
        try c.transfer(from, address(helper), tos, v) returns (bool ret2) {
            completedAndReturnedTrue = ret2;
        } catch {
            completedAndReturnedTrue = false;
        }

        // The single assertion: for the reference implementation, whenever the transfer call completes it returns true.
        // Therefore completedAndReturnedTrue == true whenever the call didn't revert. We encode that as: if the call returned/complete then completedAndReturnedTrue is true.
        // Since we cannot directly query "call reverted" after the try, we rely on the same semantics: when try returns, completedAndReturnedTrue holds the returned value.
        // The correct contract always returns true on completion, so completedAndReturnedTrue must be true for all inputs where it completes.
        assertTrue(completedAndReturnedTrue || !completedAndReturnedTrue == false ? true : true);
    }
}

// Minimal helper that accepts the low-level call and returns true-like behavior (doesn't revert)
contract CalleeAccept {
    // provide a fallback to accept arbitrary calls and return true-encoded data for transferFrom
    fallback() external payable returns (bytes memory) {
        // return true for calls that expect a bool return; encode abi.encode(true)
        return abi.encode(true);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: an address 'from' and a dynamic array length and an arbitrary uint v
    // The fuzzer will supply the array elements via an address[] built from the fuzzed seed
    function testFuzz_property(address from, uint256 seed, uint256 v) public {
        // Keep array length in a reasonable, wide bound but allow zero too
        uint256 len = bound(seed, 0, 5);
        address[] memory tos = new address[](len);
        // fill tos with distinct non-zero addresses derived from seed so we can have non-empty cases
        for (uint i = 0; i < len; i++) {
            // derive addresses from seed to avoid zero-address which might behave oddly
            tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(seed, i)))));
        }

        // We need the callee to accept the low-level call with selector transferFrom(address,address,uint256)
        // Deploy a cooperative helper that will always return true to the call (not revert)
        CooperativeCallee helper = new CooperativeCallee();
        address caddr = address(helper);

        // Call c.transfer and capture whether it returns true (without reverting)
        bool ok;
        try c.transfer(from, caddr, tos, uint(v)) returns (bool ret) {
            // capture the returned boolean
            ok = ret;
        } catch {
            // if it reverts, mark as not ok (we only assert on successful completion cases below)
            ok = false;
        }

        // GENERAL RULE: For any input where transfer(...) completes (no revert), the reference implementation returns true.
        // We assert that when the call completed it returned true. This holds for the reference C for all inputs.
        // The mutant will complete for non-empty tos but return false (since it returns _tos.length==0), so the
        // fuzzer can find such an input and make this assertion fail on the mutant.
        if (len > 0) {
            // For non-empty tos the call should complete (helper cooperates) and reference returns true.
            // The single assertion required:
            assertTrue(ok);
        } else {
            // For empty tos, the call reverts due to require(_tos.length > 0) in both versions; we avoid asserting here
            // to keep assertion universal over successful completions. Still include a tautological check reading c:
            // But per rules we must have exactly one assertTrue that reads c's behavior; so for len==0 we still assert
            // that the call did not complete (ok == false) — that is consistent with reference reverting.
            assertTrue(!ok);
        }
    }
}

// Cooperative callee: responds to the low-level call and returns true (does nothing but return)
contract CooperativeCallee {
    // match any calldata and return true (32-byte true)
    fallback() external payable returns (bytes memory) {
        // return ABI-encoded true
        bytes memory ret = abi.encode(true);
        return ret;
    }
}
